/**
 * Maps a SharePoint lookup field from API format to TypeScript data source format.
 * SharePoint lookups come back as objects with Id and Title properties (or the custom name field).
 */
export async function mapSharePointLookupApiCellToDataSourceCell(
  options: MapSharePointLookupApiCellToDataSourceCellOptions,
): Promise<TableCell | undefined> {
  const { column, tableCell, row } = options;

  const lookupIdField = `${column.apiPropertyName}Id`;
  const lookupTitleField = `${column.apiPropertyName}Title`;

  let lookupId: number | undefined;
  let lookupTitle: string | undefined;

  // Try to get lookup data from different possible formats
  if (typeof tableCell === 'object' && tableCell !== null) {
    const lookupObj = tableCell as Record<string, unknown>;
    lookupId = lookupObj.Id as number;
    lookupTitle = (lookupObj.Value ?? lookupObj.Title) as string;
  } else if (row[lookupIdField]) {
    lookupId = row[lookupIdField] as number;
    lookupTitle = row[lookupTitleField] as string;
  } else if (typeof tableCell === 'number') {
    lookupId = tableCell;
  }

  if (!lookupId) {
    return undefined;
  }

  const targetTableMetadata = await getTableMetadata({
    apiMetadataTableId: column.lookupMetadata.targetTableApiMetadataTableId,
  });

  const targetTablePrimaryIdColumnLogicalName =
    targetTableMetadata.columns.find((x) => x.isPrimaryId)?.apiPropertyName ||
    'ID';
  const targetTablePrimaryNameColumnLogicalName =
    getPrimaryNameColumn(targetTableMetadata)?.apiPropertyName || 'Title';

  // Convert lookupId to string for UI compatibility (UI code expects string IDs like Dataverse)
  return {
    [targetTablePrimaryIdColumnLogicalName]: lookupId.toString(),
    [targetTablePrimaryNameColumnLogicalName]: lookupTitle || '',
  };
}

