/**
 * Formats a TypeScript lookup value to SharePoint API format for create/update.
 * SharePoint connector expects lookup values as an object with Id property.
 *
 * TypeScript format: { id: 1, title: "Item Name" }
 * API format: { Id: 1, Value: "Item Name" } or { Id: 1 }
 */
export async function formatAsSharePointLookup(
  tableMetadata: TableToTypescriptMapping,
  column: LookupColumnToTypescriptMapping,
  rowData: NotNullOrUndefinedTableCell,
): Promise<{ Id: number; Value?: string } | undefined> {
  const anyRowData = rowData as Record<string, unknown>;

  // Try different possible ID property names
  // SharePoint uses "ID" (uppercase), but we also check lowercase variations for compatibility
  const idProp = column.lookupMetadata.targetTableApiMetadataTableId + 'id';
  const idPropUppercase =
    column.lookupMetadata.targetTableApiMetadataTableId + 'Id';

  const lookupId =
    anyRowData?.[idProp] ||
    anyRowData?.[idPropUppercase] ||
    anyRowData?.id ||
    anyRowData?.Id ||
    anyRowData?.ID; // SharePoint standard uppercase ID

  if (!lookupId) {
    return undefined;
  }

  // SharePoint expects numeric IDs
  const numericId =
    typeof lookupId === 'number' ? lookupId : parseInt(String(lookupId), 10);

  if (Number.isNaN(numericId)) {
    logWarning('formatAsSharePointLookup', {
      type: 'InvalidLookupIdFormat',
      data: {
        ...getTableAndColumnEventData(tableMetadata, column),
        lookupId: String(lookupId),
      },
    });
    return undefined;
  }

  // SharePoint connector expects lookup as object with Id property
  // Try to also include Value if available for better compatibility
  const lookupValue =
    anyRowData?.Value ||
    anyRowData?.value ||
    anyRowData?.Title ||
    anyRowData?.title;

  if (lookupValue && typeof lookupValue === 'string') {
    return { Id: numericId, Value: lookupValue };
  }

  return { Id: numericId };
}

/**
 * Formats a TypeScript single-choice value to SharePoint API format for create/update.
 * SharePoint connector expects single Choice values as an object with Value property.
 */
export function formatSharePointChoiceForApi(
  tableMetadata: TableToTypescriptMapping,
  column: ChoiceColumnToTypescriptMapping,
  tableCell: NotNullOrUndefinedTableCell,
): { Value: string } | string | undefined {
  if (tableCell === null || tableCell === undefined) {
    return undefined;
  }

  // If it's already a string, validate against known options and return as object
  if (typeof tableCell === 'string') {
    const trimmedValue = tableCell.trim();

    if (!trimmedValue) {
      return undefined;
    }

    // Find matching option by label or API value
    const lowercaseValue = trimmedValue.toLowerCase();
    const option = column.optionSetMetadata.options.find((x) => {
      return (
        x.label.toLowerCase().trim() === lowercaseValue ||
        String(x.apiValue).toLowerCase().trim() === lowercaseValue
      );
    });

    if (option) {
      return { Value: String(option.apiValue) };
    }

    // If no matching option found, log warning but still try to use the value
    logWarning('formatSharePointChoiceForApi', {
      type: 'UnmappedChoiceValue',
      data: {
        ...getTableAndColumnEventData(tableMetadata, column),
        providedValue: trimmedValue,
      },
    });

    // Return as object anyway - SharePoint will validate
    return { Value: trimmedValue };
  }

  logWarning('formatSharePointChoiceForApi', {
    type: 'InvalidChoiceValueType',
    data: {
      ...getTableAndColumnEventData(tableMetadata, column),
      receivedType: typeof tableCell,
    },
  });

  return undefined;
}

/**
 * Formats a SharePoint multi-choice field from API string to TypeScript array format.
 * SharePoint returns multi-choice as semicolon-separated string with "#" delimiters.
 */
export function formatSharePointChoicesAsStringArray(
  tableMetadata: TableToTypescriptMapping,
  column: ChoiceColumnToTypescriptMapping,
  tableCell: NotNullOrUndefinedTableCell,
): TableCell {
  if (typeof tableCell !== 'string') {
    logWarning('formatSharePointChoicesAsStringArray', {
      type: 'InvalidChoiceValueType',
      data: getTableAndColumnEventData(tableMetadata, column),
    });
    return tableCell;
  }

  // SharePoint multi-choice format: ";#Choice1;#Choice2;#"
  // Remove leading/trailing ";#" and split by ";#"
  const cleanedValue = tableCell.replace(/^;#/, '').replace(/;#$/, '');

  if (!cleanedValue) {
    return [];
  }

  return cleanedValue
    .split(';#')
    .map((item) => item.trim())
    .filter((item) => item.length > 0);
}

/**
 * Formats a TypeScript multi-choice array to SharePoint API format.
 * SharePoint expects semicolon-separated string with "#" delimiters or JSON array for REST API.
 */
export function formatSharePointChoicesForApi(
  tableMetadata: TableToTypescriptMapping,
  column: ChoiceColumnToTypescriptMapping,
  tableCell: NotNullOrUndefinedTableCell,
  useLegacyFormat: boolean = false,
): TableCell {
  // Handle array input (most common case for multi-select)
  if (Array.isArray(tableCell)) {
    const results: string[] = [];
    const unmappedChoiceValues: string[] = [];

    for (const item of tableCell) {
      if (item === null || item === undefined) {
        continue;
      }

      const itemAsString = String(item);
      const lowercaseItem = itemAsString.toLowerCase().trim();

      // Find matching option by label or API value
      const option = column.optionSetMetadata.options.find((x) => {
        return (
          x.label.toLowerCase().trim() === lowercaseItem ||
          String(x.apiValue).toLowerCase().trim() === lowercaseItem
        );
      });

      if (option) {
        // Use the label for SharePoint (not the numeric value)
        results.push(String(option.apiValue));
      } else {
        unmappedChoiceValues.push(lowercaseItem);
      }
    }

    if (unmappedChoiceValues.length > 0) {
      logWarning('formatSharePointChoicesForApi', {
        type: 'UnmappedChoicesValues',
        data: {
          ...getTableAndColumnEventData(tableMetadata, column),
          unmappedChoiceValues: unmappedChoiceValues.join(','),
        },
      });
    }

    if (results.length === 0) {
      return null;
    }

    if (useLegacyFormat) {
      // Legacy format: ";#Choice1;#Choice2;#"
      return `;#${results.join(';#')};#`;
    } else {
      // Modern format: { results: [...] }
      return { results };
    }
  } else {
    logWarning('formatSharePointChoicesForApi', {
      type: 'InvalidChoiceValueType',
      data: getTableAndColumnEventData(tableMetadata, column),
    });
  }

  return undefined;
}

